//! the zones' *present-day* ones: historical transitions are not modelled.

/// A recurring DST rule: `week` 1-4 selects the Nth `dow` of the month, 5 the
/// last; `sec` is the transition's local time as seconds past midnight.
pub const Rule = struct {
    start_month: u8,
    start_week: u8,
    start_dow: u8,
    start_sec: i32,
    end_month: u8,
    end_week: u8,
    end_dow: u8,
    end_sec: i32,
};

pub const Zone = struct {
    name: []const u8,
    canon: u16,
    std_offset_sec: i32,
    dst_save_sec: i32 = 0,
    rule: ?Rule = null,
    /// Slice of `trans_times`/`trans_offsets` holding this zone's historical
    /// transitions; `first_offset_sec` applies before the earliest of them.
    trans_start: u32 = 0,
    trans_len: u32 = 0,
    first_offset_sec: i32 = 0,
};

